# End-to-end check of the tray app: touch on/off, quality change and quit, driven
# through the real tray menu, with tablet swipes generated by `adb shell input`.
$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W {
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern IntPtr FindWindow(string cls, string title);
    [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h, uint msg, IntPtr wp, IntPtr lp);
    [DllImport("user32.dll")] public static extern bool AllowSetForegroundWindow(int pid);
}
"@

$exe = Join-Path $PSScriptRoot "..\out\Tandem.exe"
$log = Join-Path $env:APPDATA "Tandem\host.log"
$adb = Join-Path $env:LOCALAPPDATA "Android\Sdk\platform-tools\adb.exe"

function Wait-Log($pattern, $after = 0, $timeoutSec = 30) {
    for ($i = 0; $i -lt $timeoutSec * 4; $i++) {
        $lines = @(Get-Content $log -ErrorAction SilentlyContinue)
        $hit = $lines | Select-Object -Skip $after | Select-String -Pattern $pattern | Select-Object -First 1
        if ($hit) { return $hit.Line }
        Start-Sleep -Milliseconds 250
    }
    throw "timed out waiting for '$pattern'"
}
function LineCount { @(Get-Content $log -ErrorAction SilentlyContinue).Count }
function Menu($keys) {
    $h = [W]::FindWindow("TandemTray", "Tandem")
    if ($h -eq [IntPtr]::Zero) { throw "tray window not found" }
    [W]::AllowSetForegroundWindow(-1) | Out-Null
    [W]::PostMessage($h, 0x8001, [IntPtr]::Zero, [IntPtr]0x0202) | Out-Null  # WM_APP+1, WM_LBUTTONUP
    Start-Sleep -Milliseconds 700
    foreach ($k in $keys) { [System.Windows.Forms.SendKeys]::SendWait($k); Start-Sleep -Milliseconds 300 }
}
function Swipe { & $adb shell input swipe 900 700 1500 1000 250; Start-Sleep -Milliseconds 400 }

Get-Process Tandem,TandemHost -ErrorAction SilentlyContinue | Stop-Process -Force
Start-Sleep -Milliseconds 500
Start-Process $exe
"1. started:             " + (Wait-Log "Encoder:")
Swipe; Swipe

$n = LineCount
Menu @("t")
"2. touch toggled:       " + (Wait-Log "Settings: touch=0" $n 5)
Swipe; Swipe

$n = LineCount
Menu @("v", "f")
"3. quality -> fastest:  " + (Wait-Log "Settings: .*quality=50" $n 5)
"   session ended:       " + (Wait-Log "Input this session" $n)
"   restarted at:        " + (Wait-Log "Encoder ready.*1600x1068" $n)
Swipe

$n = LineCount
Menu @("t")
"4. touch back on:       " + (Wait-Log "Settings: touch=1" $n 5)
Menu @("v", "b")
"   quality -> balanced: " + (Wait-Log "Settings: .*quality=75" $n 5)
"   restarted at:        " + (Wait-Log "Encoder ready.*2400x1602" $n)

$n = LineCount
Menu @("q")
"5. quit:                " + (Wait-Log "Tandem host stopped" $n 15)
Start-Sleep -Milliseconds 500
"   process still running: " + [bool](Get-Process Tandem,TandemHost -ErrorAction SilentlyContinue)
"--- input counters per session:"
Get-Content $log | Select-String "Input this session" | ForEach-Object { "   " + $_.Line }
